if module_no != '1':
    slides=json.loads((OUT/'content.json').read_text(encoding='utf-8'))

def h(s): return escape(s).replace('\n','<br>')
def render(s):
    kind=s['kind']; body=''
    if kind in ('cover','closing'):
        body=f'<p class="hero-lead">{h(s["lead"])}</p><div class="proof">{h(s["proof"])}</div>'
    elif kind in ('steps','roadmap'):
        body='<div class="steps '+kind+'">'+''.join(f'<div class="step"><span class="num">{h(n)}</span><h2>{h(t)}</h2><p>{h(d)}</p></div>' for n,t,d in s['items'])+'</div>'
    elif kind in ('rows','sources'):
        body='<div class="rows">'+''.join(f'<div class="row"><strong>{h(t)}</strong><p>{h(d)}</p></div>' for t,d in s['rows'])+'</div>'
        if 'lead' in s:body+='<p class="lead">'+h(s['lead'])+'</p>'
    elif kind=='flow':
        body='<div class="flow">'+''.join(('<span class="arrow" aria-hidden="true">→</span>' if i else '')+f'<div class="node"><h2>{h(t)}</h2><p>{h(d)}</p></div>' for i,(t,d) in enumerate(s['items']))+'</div><p class="lead">'+h(s['lead'])+'</p>'
    elif kind=='compare':
        body='<div class="compare">'+''.join('<div><h2>'+h(col[0])+'</h2><ul>'+''.join('<li>'+h(t)+'</li>' for t in col[1])+'</ul></div>' for col in (s['left'],s['right']))+'</div>'
    elif kind=='code':
        body='<div class="code-layout"><pre>'+escape(s['code'])+'</pre><p>'+h(s['lead'])+'</p></div>'
    elif kind=='quote':
        body='<blockquote>'+h(s['quote'])+'</blockquote><p class="lead">'+h(s['lead'])+'</p>'
    return body
