js='''
const slides=[...document.querySelectorAll('.slide')];const notes=NOTES;let current=0;
const panel=document.getElementById('notes');
function resize(){let scale=Math.min(innerWidth/1280,innerHeight/720);document.getElementById('viewport').style.width=1280*scale+'px';document.getElementById('viewport').style.height=720*scale+'px';document.getElementById('stage').style.transform='scale('+scale+')'}
function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.hidden=i!==current);panel.textContent=notes[current];document.getElementById('progress').style.width=(current+1)/slides.length*100+'%';history.replaceState(null,'','#'+(current+1));document.title='Модуль 1 · '+(current+1)+'/'+slides.length}
function toggleNotes(){panel.hidden=!panel.hidden;panel.textContent=notes[current]}
document.getElementById('prev').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.getElementById('notesBtn').onclick=toggleNotes;document.getElementById('printBtn').onclick=()=>print();
addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}else if(e.key==='Home')show(0);else if(e.key==='End')show(slides.length-1);else if(e.key.toLowerCase()==='n')toggleNotes();else if(e.key.toLowerCase()==='p')print();else if(e.key==='Escape')panel.hidden=true});
addEventListener('resize',resize);resize();show(Math.max(0,(parseInt(location.hash.slice(1),10)||1)-1));
'''.replace('NOTES',notes)
html='<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Архитектура второго мозга · Codex</title><style>'+css+'</style></head><body><div id="hint">← → слайды · N заметки · P печать</div><main id="viewport"><div id="stage">'+''.join(parts)+'</div></main><aside id="notes" hidden aria-label="Заметки ведущего"></aside><nav id="controls" aria-label="Управление"><button id="prev" aria-label="Предыдущий слайд">←</button><button id="next" aria-label="Следующий слайд">→</button><button id="notesBtn">Заметки N</button><button id="printBtn">PDF / печать</button></nav><div id="progress"></div><script>'+js+'</script></body></html>'
OUT.mkdir(parents=True,exist_ok=True)
html=html.replace('Модуль 1 ·', 'Модуль '+module_no+' ·').replace('Архитектура второго мозга · Codex', slides[0]['title'].replace('\n',' ')+' · Codex')
if module_no!='1':
    html=html.replace('ПИЛОТ 0.1','ЧЕРНОВИК 0.2 · БЕЗ ПРОГОНА')
(OUT/(stem+'.html')).write_text(html,encoding='utf-8')
md='# Архитектура второго мозга в Codex · сценарий презентации\n\nАлександр Кузнецов и команда AI-Потока. Пилот 0.1, 2 ноября 2026.\n\nСценарий редактируется в `tools/build_presentation.py`; сборщик обновляет HTML и этот MD. Полезный результат модуля — сохранённая задача и проверка нового разговора.\n'
for i,s in enumerate(slides,1):
    md+=f'\n## Слайд {i}. '+s['title'].replace('\n',' ')+'\n\n'+s['k']+'\n\n'
    for key in ('lead','quote','proof'):
        if key in s:md+=s[key]+'\n\n'
    if 'code' in s:md+='```text\n'+s['code']+'\n```\n\n'
    for item in s.get('items',[]):md+=' — '.join(item)+'\n\n'
    for item in s.get('rows',[]):md+=' — '.join(item)+'\n\n'
    for key in ('left','right'):
        if key in s:md+=s[key][0]+': '+ '; '.join(s[key][1])+'.\n\n'
    md+='**Ведущему:** '+s['note']+'\n'
if module_no!='1':
    md=md.replace('# Архитектура второго мозга в Codex · сценарий презентации', '# Модуль '+module_no+' · '+slides[0]['title'].replace('\n',' ')+' · сценарий презентации').replace('Пилот 0.1,', 'Черновик 0.2 без функционального прогона,').replace('Полезный результат модуля — сохранённая задача и проверка нового разговора.', 'Результат и последовательность этого модуля указаны в START.md. Экспорт слайдов не является прогоном установки или функциональности.')
(OUT/'SLIDES.md').write_text(md,encoding='utf-8')
print('Slides:',len(slides),'HTML bytes:',len(html.encode()))
